if(!paused){const we=1-Math.exp(-dt*4);willowPointer.x+=(willowPointer.targetX-willowPointer.x)*we;willowPointer.y+=(willowPointer.targetY-willowPointer.y)*we;willowPointer.strength+=((storyIsOpen()?0:willowPointer.targetStrength)-willowPointer.strength)*we;const ease=1-Math.exp(-dt*3.8);depthPointer.x+=(depthPointer.targetX-depthPointer.x)*ease;depthPointer.y+=(depthPointer.targetY-depthPointer.y)*ease;world.style.setProperty('--mx',(-depthPointer.x*11)+'px');world.style.setProperty('--my',(-depthPointer.y*7)+'px');world.style.setProperty('--camera-progress',Math.min(1,cameraRig.push/1.3));world.style.setProperty('--tree-x',(-depthPointer.x*3)+'px');world.style.setProperty('--tree-y',(-depthPointer.y*2)+'px');world.style.setProperty('--far-x',(depthPointer.x*1.5)+'px');world.style.setProperty('--mist-x',(-depthPointer.x*14)+'px');}
if(!paused||cameraJourney){
 if(cameraJourney){
 const j=cameraJourney;const waitingForPlate=j.to>0&&j.elapsed===0&&!destinationView.isReady(dark);if(!waitingForPlate)j.elapsed+=cameraDt;const u=Math.min(1,j.elapsed/j.duration);
 const sample=q=>{const e=q*q*q*(10+q*(-15+6*q)),carry=q*Math.pow(1-q,3)*j.duration,bow=16*q*q*Math.pow(1-q,2),bend=cameraPath?.bend||[(j.fromX+j.toX)/2,(j.fromY+j.toY)/2];return [j.from+(j.to-j.from)*q,j.fromX+(j.toX-j.fromX)*e+(j.startVX||0)*carry+(bend[0]-(j.fromX+j.toX)/2)*bow*.22,j.fromY+(j.toY-j.fromY)*e+(j.startVY||0)*carry+(bend[1]-(j.fromY+j.toY)/2)*bow*.22]};
 const point=sample(u),ahead=sample(Math.min(1,u+.001)),behind=sample(Math.max(0,u-.001)),span=(Math.min(1,u+.001)-Math.max(0,u-.001))*j.duration;
 [cameraRig.push,cameraRig.focusX,cameraRig.focusY]=point;[cameraRig.vPush,cameraRig.vX,cameraRig.vY]=ahead.map((v,i)=>(v-behind[i])/span);
 if(u===1){const done=j.onComplete;cameraRig.push=j.to;cameraRig.focusX=j.toX;cameraRig.focusY=j.toY;cameraRig.vPush=cameraRig.vX=cameraRig.vY=0;cameraJourney=null;if(j.to===0){cameraPath=null;activeDestination=null;}done?.();}
 }

 cameraRig.push=Math.max(0,Math.min(CAMERA_LIMIT,cameraRig.push));world.classList.toggle('camera-travel',cameraRig.push>.01||cameraRig.target>.01);
}

