const returnButton=document.createElement('button');returnButton.className='return-world';returnButton.textContent='← Return to the world';returnButton.addEventListener('click',()=>{clearTimeout(cameraTimer);cameraBusy=false;guide.stop();resetCamera()});world.append(returnButton);
