function approachLandmark(id){if(storyIsOpen()||cameraBusy||reduce.matches||lastStoryPlace===id)return;clearTimeout(cameraReturnTimer);guide.stop();hoveredPlace=id;document.querySelectorAll('.pin').forEach(el=>el.classList.toggle('hover-active',el.dataset.place===id));travelTo(id);cameraJourney.onComplete=()=>{storyTrail.arrive(id,()=>{if(hoveredPlace===id&&!storyIsOpen())openPaper(id)})};}
function leaveLandmark(id){if(!storyIsOpen())storyTrail.cancel();if(lastStoryPlace===id)lastStoryPlace=null;if(hoveredPlace!==id)return;hoveredPlace=null;clearTimeout(cameraReturnTimer);document.querySelectorAll('.pin').forEach(el=>el.classList.remove('hover-active'));if(!storyIsOpen()&&!cameraBusy)resetCamera();}
