function drawCarFlight(ctx,t,w,h,dark,carActor){if(carActor){const q=carActor.q;const {x:cx,y:cy}=flightPose(carActor,w,h);ctx.save();flightHighlight(ctx,cx,cy,58*carActor.scale,dark);ctx.translate(cx,cy);const carScale=(.76+Math.sin(q*Math.PI)*.12)*carActor.scale;ctx.scale(carActor.direction<0?-carScale:carScale,carScale);ctx.globalAlpha=.82;ctx.rotate(Math.cos(q*Math.PI*2)*.06);ctx.shadowColor='#0b233855';ctx.shadowBlur=6;ctx.fillStyle='#9ed3dc';ctx.beginPath();ctx.moveTo(-25,4);ctx.lineTo(-23,-4);ctx.lineTo(-12,-7);ctx.lineTo(-7,-16);ctx.quadraticCurveTo(2,-19,12,-15);ctx.lineTo(19,-6);ctx.lineTo(28,-3);ctx.lineTo(29,6);ctx.closePath();ctx.fill();ctx.fillStyle='#dce7dc';ctx.beginPath();ctx.moveTo(-10,-7);ctx.lineTo(-5,-15);ctx.lineTo(10,-14);ctx.lineTo(16,-6);ctx.closePath();ctx.fill();ctx.fillStyle='#274655';ctx.beginPath();ctx.moveTo(-7,-8);ctx.lineTo(-3,-13);ctx.lineTo(2,-13);ctx.lineTo(2,-7);ctx.closePath();ctx.fill();ctx.beginPath();ctx.moveTo(5,-13);ctx.lineTo(10,-12);ctx.lineTo(14,-7);ctx.lineTo(5,-7);ctx.fill();ctx.strokeStyle='#4b7986';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(3,-5);ctx.lineTo(3,5);ctx.stroke();ctx.fillStyle='#172b32';for(const xx of [-16,18]){ctx.beginPath();ctx.ellipse(xx,6,5,6,0,0,7);ctx.fill();ctx.fillStyle='#bfc5b6';ctx.beginPath();ctx.arc(xx,6,2.4,0,7);ctx.fill();ctx.fillStyle='#172b32'}ctx.save();ctx.shadowColor='#fff1b8';ctx.shadowBlur=dark?22:12;ctx.fillStyle='#fff7d7';ctx.fillRect(25,-2,5,5);ctx.restore();ctx.fillStyle='#dfccab';ctx.fillRect(-27,2,3,3);if(dark){const g=ctx.createLinearGradient(29,0,110,0);g.addColorStop(0,'#fff0bba0');g.addColorStop(1,'#f4e8aa00');ctx.fillStyle=g;ctx.beginPath();ctx.moveTo(28,-1);ctx.lineTo(110,-13);ctx.lineTo(110,18);ctx.lineTo(28,3);ctx.fill()}ctx.restore()}}
function drawPhoenixFlight(ctx,t,w,h,dark,phoenixActor){if(phoenixActor){const q=phoenixActor.q;const {x:px,y:py}=flightPose(phoenixActor,w,h);ctx.save();ctx.globalAlpha=.84;flightHighlight(ctx,px,py,65*phoenixActor.scale,dark);ctx.translate(px,py);const sc=(w<700?.62:.85)*phoenixActor.scale;ctx.scale(phoenixActor.direction>0?-sc:sc,sc);ctx.rotate(-.12);const flap=Math.sin(t*3.5)*11;ctx.shadowColor='#ffad3d';ctx.shadowBlur=dark?14:5;ctx.strokeStyle='#cd492b';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(6,1);ctx.quadraticCurveTo(20,11,43,9+Math.sin(t*2)*6);ctx.moveTo(7,3);ctx.quadraticCurveTo(23,18,51,20+Math.sin(t*2.2)*8);ctx.stroke();const phoenixWing=ctx.createLinearGradient(0,0,28,-30);phoenixWing.addColorStop(0,'#ffe1a0');phoenixWing.addColorStop(.4,'#e78b3d');phoenixWing.addColorStop(1,'#b83b25');ctx.fillStyle=phoenixWing;ctx.beginPath();ctx.moveTo(0,1);ctx.quadraticCurveTo(-3,-20-flap,28,-24-flap);ctx.quadraticCurveTo(17,-6,5,5);ctx.quadraticCurveTo(25,11,31,21+flap*.5);ctx.quadraticCurveTo(4,21,0,1);ctx.fill();ctx.fillStyle='#efb54b';ctx.beginPath();ctx.ellipse(0,1,8,3,-.1,0,7);ctx.fill();ctx.beginPath();ctx.moveTo(-5,0);ctx.lineTo(-13,-5);ctx.lineTo(-10,1);ctx.lineTo(-16,3);ctx.lineTo(-5,3);ctx.fill();for(let j=0;j<9;j++){ctx.fillStyle=`rgba(255,172,55,${(1-j/9)*.45})`;ctx.beginPath();ctx.arc(35+j*8,12+Math.sin(t*3+j)*7,1.4-j*.1,0,7);ctx.fill()}ctx.restore()}}
